@startuml

class Customer {
  + Name : string
  + AccountNumber : string
}

class Broker {
  + Name : string
}

class Policy {
  + Type : string
}

class Offer {
  + Date : date
  + Terms : string
}

class Contract {
  + Date : date
  + BillingCycle : string
  + Price : float
}

class ClaimCase {
  + CaseId : string
  + Status : string
}

class Estimator {
  + Name : string
  + Expertise : string
}

class EstimatorReport {
  + ReportDate : date
  + Content : string
}

class Compensation {
  + Amount : float
  + DatePaid : date
}

Broker "1" -- "*" Customer : manages
Customer "1" -- "*" Offer : receives
Customer "1" -- "*" Contract : signs
Customer "1" -- "*" ClaimCase : files
Offer "0..1" -- "1" Contract : becomes
Contract "1" -- "1" Policy : covers
Contract "1" -- "0..*" ClaimCase : involves
ClaimCase "1" *-- "1..*" EstimatorReport : contains
Estimator "1" -- "*" EstimatorReport : issues
ClaimCase "1" -- "0..1" Compensation : results in

@enduml

